export function truncate(str, maxGraphemes) {
  const segmenter = new Intl.Segmenter('en', { granularity: 'grapheme' });
  const clusters = [...segmenter.segment(str)].map(s => s.segment);
  if (clusters.length <= maxGraphemes) return str;
  return clusters.slice(0, maxGraphemes).join('') + '...';
}

